import { update_user_presence_settings } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    rfidMapping: Boolean,
    membersItem: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    rfidMapping: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_Entity() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_user_presence_settings, {
          input: {
            user_id: this.membersItem.user_id,
            rfid: "N/A"
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.update_user_presence_settings);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
